def _build_component_06():
    def solve(data):
        packages = data["packages"]
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        package_order = sorted(packages, reverse=True)
        initial = {name: [(bounds[0], bounds[1])]
                   for name, bounds in data.get("roots", {}).items()}
        best = None
        best_vector = None

        def active_deps(row):
            return [dep for dep in row.get("deps", [])
                    if not dep.get("feature") or dep["feature"] in features]

        def permitted(name, version, requirements):
            return (all(low <= version <= high
                        for low, high in requirements.get(name, []))
                    and version not in blocked.get(name, [])
                    and (name not in pins or version == pins[name]))

        def acyclic(edges):
            complete, active = set(), set()

            def visit(name):
                if name in active:
                    return False
                if name in complete:
                    return True
                active.add(name)
                for other in edges.get(name, []):
                    if not visit(other):
                        return False
                active.remove(name)
                complete.add(name)
                return True

            return all(visit(name) for name in edges)

        def search(chosen, requirements, edges):
            nonlocal best, best_vector
            if any(not permitted(name, version, requirements)
                   for name, version in chosen.items()):
                return
            unresolved = [name for name in requirements if name not in chosen]
            if not unresolved:
                if not acyclic(edges):
                    return
                vector = tuple(chosen.get(name, -1) for name in package_order)
                if best_vector is None or vector > best_vector:
                    best_vector = vector
                    best = dict(chosen)
                return

            name = min(unresolved)
            rows = [row for row in packages.get(name, [])
                    if permitted(name, row["version"], requirements)]
            for row in sorted(rows, key=lambda item: item["version"], reverse=True):
                next_chosen = dict(chosen)
                next_chosen[name] = row["version"]
                next_requirements = {key: list(value)
                                     for key, value in requirements.items()}
                next_edges = {key: list(value) for key, value in edges.items()}
                deps = active_deps(row)
                next_edges[name] = [dep["name"] for dep in deps]
                for dep in deps:
                    next_requirements.setdefault(dep["name"], []).append(
                        (dep["min"], dep["max"]))
                search(next_chosen, next_requirements, next_edges)

        search({}, initial, {})
        if best is None:
            return {"error": "unsatisfiable"}
        return {"versions": best}

    return solve


def _build_component_07():
    from itertools import combinations
    import heapq

    def compatible(subset):
        active_ends = []
        for job in sorted(subset,
                          key=lambda item: (item["start"], item["end"], item["id"])):
            while active_ends and active_ends[0] <= job["start"]:
                heapq.heappop(active_ends)
            heapq.heappush(active_ends, job["end"])
            if len(active_ends) > 2:
                return False
        return True

    def solve(data):
        jobs = [job for job in data["jobs"]
                if job["id"] not in data.get("blocked", [])]
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        k = data["k"]
        best_value = None
        best_ids = None

        for subset in combinations(jobs, k):
            ids = {job["id"] for job in subset}
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            if not compatible(subset):
                continue

            value = sum(job["value"] for job in subset)
            sorted_ids = sorted(ids)
            if (best_value is None or value > best_value
                    or (value == best_value and sorted_ids > best_ids)):
                best_value, best_ids = value, sorted_ids

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}

    return solve


def _build_component_08():
    import heapq

    def solve(data):
        required = data.get("required", [])
        required_index = {node: i for i, node in enumerate(required)}
        full_mask = (1 << len(required)) - 1
        initial_mask = 0
        if data["source"] in required_index:
            initial_mask |= 1 << required_index[data["source"]]

        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        start_state = (data["source"], initial_mask, data["coupons"])
        distances = {start_state: data["start"]}
        queue = [(data["start"], *start_state)]

        while queue:
            time, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distances.get(state) != time:
                continue
            if node == data["target"] and mask == full_mask:
                return {"arrival": time}

            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                for spent in (0, 1):
                    if spent and remaining == 0:
                        continue
                    duration = edge["duration"]
                    if spent:
                        duration = max(1, duration - edge.get("discount", 0))
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask
                    if next_node in required_index:
                        next_mask |= 1 << required_index[next_node]
                    next_remaining = remaining - spent
                    next_state = (next_node, next_mask, next_remaining)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival, *next_state))

        return {"arrival": None}

    return solve


